import sys
from collections import deque

class N:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

def build(pre, ino):
    if not pre:
        return None
    root = pre[0]
    i = ino.index(root)
    node = N(root)
    node.l = build(pre[1:i + 1], ino[:i])
    node.r = build(pre[i + 1:], ino[i + 1:])
    return node

def serialize(root):
    if not root:
        return ['n']
    res = []
    q = deque([root])
    while q:
        node = q.popleft()
        if node is None:
            res.append('n')
        else:
            res.append(str(node.v))
            q.append(node.l)
            q.append(node.r)
    while res and res[-1] == 'n':
        res.pop()
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    pre = list(map(int, data[1:1 + n]))
    ino = list(map(int, data[1 + n:1 + 2 * n]))
    root = build(pre, ino)
    print(' '.join(serialize(root)))

